import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./register.css";

const Register = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
    role: "Patient",
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // perform register logic here
    navigate("/dashboard");
  };

  return (
    <div className="register-container">
      <div className="left-panel">
        <h1>Welcome to <span className="highlight">MediVault</span></h1>
        <p>Your secure digital health vault.</p>
        <img src="/images/medtech-illustration.png" alt="MedTech" />
      </div>

      <div className="right-panel glass">
        <h2>Create Account</h2>
        <form onSubmit={handleSubmit} className="register-form">
          <input
            type="text"
            placeholder="Full Name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            required
          />
          <input
            type="email"
            placeholder="Email Address"
            name="email"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <input
            type="password"
            placeholder="Password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            required
          />

          {/* Modern dropdown */}
          <div className="custom-select">
            <select name="role" value={formData.role} onChange={handleChange}>
              <option value="Patient">Patient</option>
              <option value="Doctor">Doctor</option>
              <option value="Hospital">Hospital</option>
            </select>
            <span className="dropdown-icon">▼</span>
          </div>

          <button type="submit">Register</button>

          <div className="divider">or</div>

          <button type="button" className="google-btn">
            <img src="/icons/google.svg" alt="Google" /> Continue with Google
          </button>

          <p className="login-text">
            Already have an account? <Link to="/login">Login here</Link>
          </p>
        </form>
      </div>
    </div>
  );
};

export default Register;
